using System;using System.Collections.Generic;using System.Text;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckFishing {
public sealed class FishingMatch:SportsEventSession {
 public FishingStream[] streams;public SportsEventCamera[] streamCameras;public SportsCameraFit[] framing;public int seed=17381;[Range(0,.2f)]public float fishAcceleration=.12f;public float minimumSpeed=2.8f,maximumSpeed=4.5f,challengeSeconds=600,poisonMaximum=.2f,burstDuration=5,breakDuration=3,density=1;public FishingRules rules=new FishingRules();public double Clock{get;private set;}public float Countdown{get;private set;}public int HumanViews{get;private set;}public int ScheduleCount{get;private set;}public int[] Owners{get;private set;}=new int[4];public int Spectator{get;private set;}public bool Playing=>Live&&Countdown<=0;
 struct CatchEvent{public int slot;public FishPlan plan;public bool caught;public float fraction;}readonly List<CatchEvent> events=new List<CatchEvent>(32);readonly List<FishPlan> upcoming=new List<FishPlan>(32);FishingDirector director;FishPlan next;readonly double[] think=new double[4];readonly float[] aim=new float[4];readonly long[] selected={-1,-1,-1,-1};readonly System.Random[] brains=new System.Random[4];readonly float[] eliminatedAt=new float[4];int spectated=-1;readonly StringBuilder text=new StringBuilder(800);
 public override string Title=>"TRUCK FISHING";public override int MinimumPlayers=>1;public override int MaximumPlayers=>4;public override bool UsesAction=>false;public override bool SupportsSplitAIViews=>true;public override int OptionCount=>1;public override int WeatherCount=>1;public override bool MultiViewHUD=>true;public override string OptionLabel=>setup.count==1?"ENDLESS SOLO SURVIVAL":"SIMULTANEOUS SURVIVAL";public override string SourcePolicy=>"Only LEFT / RIGHT moves the net. Your truck stays on the dock. Shared sticks are independent; alternate left/right to shake occasional rubbish from the net; no action button. AI has its own stream and does not consume human views.";
 public override string ControlCaption(int slot){var p=setup.players[slot];return p.source==BowlingSource.AI?"AI · "+p.difficulty:p.source==BowlingSource.Keyboard?p.left.ToString().Replace("Arrow","").ToUpper()+" / "+p.right.ToString().Replace("Arrow","").ToUpper():p.source==BowlingSource.RightStick?"RIGHT STICK · HORIZONTAL":"LEFT STICK · HORIZONTAL";}
 public override string Help=>"Your truck stays parked. Move only the net left and right: keyboard left/right keys or your assigned stick. Catch orange small fish for 1 lb and blue tuna for 5 lb. Missed good fish add the same weight; 20 lb missed eliminates you. Avoid the violet SHARK / X poison: catching it eliminates immediately, letting it pass is safe. The oval net opening is the catch area. Fish enter from beyond the visible upstream river. Occasionally a tyre, canister or river rock snags the net: release the stick, then alternate LEFT and RIGHT four times to clear it. Fish continue swimming safely past that blocked net without missed-weight penalties; the shared survival clock and other players continue. Automatic recovery after six seconds prevents a softlock. Rubbish never awards or removes pounds. Swimming fish do not home toward you. Streams receive the same seeded schedule and warning time. Solo has no score or time cap: survive as long as you can and improve your personal best. Multiplayer is last survivor; simultaneous final failures produce a draw. Lulls do not erase missed weight. Escape / assigned Start pauses every stream, preserving fish and score. Reconnect or explicitly replace a source, release controls and freshly confirm. Rematches retain names, colors and assignments.";
 public override string Header=>Title+" · "+(Countdown>0?Mathf.CeilToInt(Countdown).ToString():Clock.ToString("F1")+"s");public override string Status=>"SMALL 1 LB · TUNA 5 LB · SHARK / X = POISON · MISS 20 LB AND YOU'RE OUT";public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append(setup.players[i].name).Append(" · ").Append(rules.caught[i]).Append(" CAUGHT · ").Append(rules.missed[i]).Append("/20 MISSED · ").Append(rules.alive[i]?"FISHING":rules.reason[i]).Append('\n');return text.ToString();}}
 public override string Results=>(setup.count==1?"SURVIVED "+eliminatedAt[0].ToString("F1")+"s":rules.Winner<0?"SIMULTANEOUS ELIMINATION · DRAW":setup.players[rules.Winner].name+" IS LAST SURVIVOR")+"\n\n"+Standings+"\nSOLO BEST "+SportsPrefs.GetFloat("TruckFishing.SurvivalPB",0).ToString("F1")+"s · "+SportsPrefs.GetInt("TruckFishing.CaughtPB",0)+" lb";
 public override string ViewText(int view){int i=HumanViews==0?Spectator:Owners[view];return "<color=#"+ColorUtility.ToHtmlStringRGB(setup.players[i].color)+">"+setup.players[i].name+"</color> · "+(Countdown>0?Mathf.CeilToInt(Countdown).ToString():(rules.alive[i]?Clock:eliminatedAt[i]).ToString("F1")+"s")+" · "+rules.Remaining+" REMAIN\n"+rules.caught[i]+" LB CAUGHT  |  "+rules.missed[i]+" / 20 LB MISSED"+(!rules.alive[i]?" · "+rules.reason[i]:rules.missed[i]>=15?" · DANGER":"");}
 protected override void BeginGame(){rules.Reset(setup.count);Clock=0;Countdown=3;ScheduleCount=0;upcoming.Clear();events.Clear();director=new FishingDirector(seed){acceleration=fishAcceleration,minimumSpeed=minimumSpeed,maximumSpeed=maximumSpeed,density=density,maxNetSpeed=streams[0].netSpeed,challengeSeconds=challengeSeconds,poisonMaximum=poisonMaximum,burstSeconds=burstDuration,breakSeconds=breakDuration};next=EntryPlan(director.Next());for(int i=0;i<4;i++){streams[i].gameObject.SetActive(i<setup.count);if(i<setup.count)streams[i].ResetStream();brains[i]=new System.Random(seed+i*7919+31);think[i]=0;aim[i]=0;selected[i]=-1;eliminatedAt[i]=0;}Layout();for(int i=0;i<menus.viewTexts.Length;i++){var label=menus.viewTexts[i];label.rectTransform.sizeDelta=new Vector2(730,58);var backing=label.transform.parent.Find("View data backing").GetComponent<RectTransform>();backing.sizeDelta=new Vector2(750,76);}}
 void Layout(){HumanViews=SportsCameraOptions.Select(setup,Owners);var enabled=new List<Camera>(4);for(int i=0;i<4;i++)streamCameras[i].view.enabled=false;if(HumanViews==0){Spectator=0;streamCameras[0].view.enabled=true;streamCameras[0].view.rect=new Rect(0,0,1,1);enabled.Add(streamCameras[0].view);}else for(int v=0;v<HumanViews;v++){int owner=Owners[v];streamCameras[owner].view.enabled=true;streamCameras[owner].view.rect=LWS.TruckCornhole.CornholeMatch.ViewRect(HumanViews,v);enabled.Add(streamCameras[owner].view);}cameras=enabled.ToArray();spectated=-1;}
 protected override void Simulate(float dt){if(Countdown>0){Countdown=Mathf.Max(0,Countdown-dt);return;}Clock+=dt;events.Clear();while(next.Spawn<=Clock+9){upcoming.Add(next);next=EntryPlan(director.Next());if(upcoming.Count>64)throw new InvalidOperationException("Fishing director density exceeded its bounded warning queue");}for(int n=upcoming.Count-1;n>=0;n--)if(upcoming[n].Spawn<=Clock){var plan=upcoming[n];for(int i=0;i<setup.count;i++)if(rules.alive[i])streams[i].Spawn(plan);ScheduleCount++;upcoming.RemoveAt(n);}for(int i=0;i<setup.count;i++){if(!rules.alive[i])continue;float input=setup.players[i].source==BowlingSource.AI?AI(i):commands[i].x;bool blocked=streams[i].clearing.Active;streams[i].clearing.Tick(input,dt,setup.players[i].source==BowlingSource.AI,(int)setup.players[i].difficulty);if(blocked)streams[i].StopNet();else streams[i].MoveNet(input,dt);streams[i].Advance(Clock,dt,this);if(streams[i].Overflowed)throw new InvalidOperationException("Fishing model pool unexpectedly full");}
 events.Sort((a,b)=>{int value=a.fraction.CompareTo(b.fraction);if(value!=0)return value;if(a.plan.kind==FishKind.Poison&&b.plan.kind!=FishKind.Poison)return -1;if(b.plan.kind==FishKind.Poison&&a.plan.kind!=FishKind.Poison)return 1;value=a.plan.id.CompareTo(b.plan.id);return value!=0?value:a.slot.CompareTo(b.slot);});foreach(var e in events){int missed=rules.missed[e.slot];bool was=rules.alive[e.slot];bool blocked=streams[e.slot].clearing.Active;if(!rules.Resolve(e.slot,e.plan.id,blocked?FishKind.Debris:e.plan.kind,e.caught))continue;if(blocked)continue;if(e.plan.kind==FishKind.Debris){if(e.caught){streams[e.slot].clearing.Begin(e.plan.id);streams[e.slot].CatchEffect();feedback.Play(2,0,true);}continue;}if(e.caught){streams[e.slot].CatchEffect();feedback.Play(e.plan.kind==FishKind.Small?0:e.plan.kind==FishKind.Large?1:3,0,true);Pulse(e.slot,.15f,.06f);}else if(e.plan.kind!=FishKind.Poison)feedback.Play(2,0,true);if(missed<15&&rules.missed[e.slot]>=15)feedback.Play(4,0,true);if(was&&!rules.alive[e.slot]){eliminatedAt[e.slot]=(float)Clock;streams[e.slot].HideFish();feedback.Play(3,0,true);}}
 rules.FinishStep();if(rules.Complete){if(setup.count>1&&rules.Winner>=0)feedback.Play(5,0,true);if(setup.count==1){float survival=(float)Clock;if(survival>SportsPrefs.GetFloat("TruckFishing.SurvivalPB",0))SportsPrefs.SetFloat("TruckFishing.SurvivalPB",survival);if(rules.caught[0]>SportsPrefs.GetInt("TruckFishing.CaughtPB",0))SportsPrefs.SetInt("TruckFishing.CaughtPB",rules.caught[0]);SportsPrefs.Save();}EndMatch();}}
 FishPlan EntryPlan(FishPlan p){p.entryLead=8;p.arrival+=p.entryLead;if(p.id>8&&p.id%13==0&&p.kind!=FishKind.Poison)p.kind=FishKind.Debris;return p;}
 public void Queue(int slot,FishPlan plan,bool caught,float fraction){events.Add(new CatchEvent{slot=slot,plan=plan,caught=caught,fraction=fraction});}
 float AI(int slot){var stream=streams[slot];float skill=(int)setup.players[slot].difficulty;if(Clock>=think[slot]){think[slot]=Clock+Mathf.Lerp(.45f,.13f,skill*.5f);int choice=-1;double best=double.MaxValue;for(int i=0;i<FishingStream.Capacity;i++){if(!stream.Visible(i,Clock))continue;var p=stream.plans[i];if(p.kind==FishKind.Poison||p.kind==FishKind.Debris)continue;double value=p.arrival-Clock-(p.kind==FishKind.Large?.18:0);if(value<best){best=value;choice=i;}}if(choice>=0){var p=stream.plans[choice];if(selected[slot]!=p.id){selected[slot]=p.id;double u=Math.Max(.00001,brains[slot].NextDouble()),v=brains[slot].NextDouble();float error=(float)(Math.Sqrt(-2*Math.Log(u))*Math.Cos(2*Math.PI*v))*Mathf.Lerp(.95f,.48f,skill*.5f);aim[slot]=Mathf.Clamp(p.x+error,-5.2f,5.2f);}}else aim[slot]=Mathf.MoveTowards(aim[slot],0,.5f);
 for(int i=0;i<FishingStream.Capacity;i++)if(stream.Visible(i,Clock)){var hazard=stream.plans[i];if((hazard.kind!=FishKind.Poison&&hazard.kind!=FishKind.Debris)||hazard.arrival-Clock>1.2+skill*.25)continue;if(Mathf.Abs(aim[slot]-hazard.x)<stream.radius+.5f)aim[slot]=Mathf.Clamp(hazard.x+(hazard.x>0?-1:1)*(stream.radius+.9f),-5.2f,5.2f);}}
 return Mathf.Clamp((aim[slot]-stream.NetX)*2.5f,-1,1);}
 protected override void Present(float dt){if(streams==null||framing==null)return;if(HumanViews==0&&setup.count>0){int target=(int)(Clock/12)%setup.count;if(!rules.alive[target])for(int i=0;i<setup.count;i++)if(rules.alive[i]){target=i;break;}Spectator=target;if(spectated!=target){spectated=target;for(int i=0;i<4;i++)streamCameras[i].view.enabled=i==target;cameras=new[]{streamCameras[target].view};streamCameras[target].view.rect=new Rect(0,0,1,1);}}foreach(var fit in framing)if(fit!=null&&fit.cameraTarget.enabled)fit.Apply();}
 protected override void StopGame(){if(streams!=null)foreach(var stream in streams)stream?.clearing?.ResetChallenge();}protected override void StopSounds(){}
}
}
